 	case HLS_LINK_COOLDOWN:		/* transient within goto_offline() */
 	default:
 		dd_dev_info(dd, "%s: state 0x%x: not supported\n",
 			    __func__, state);
 		ret = -EINVAL;
 		break;
 	}

 	goto done;

