 	dd_dev_err(dd, "%s: unexpected state transition from %s to %s\n",
 		   __func__, link_state_name(ppd->host_link_state),
 		   link_state_name(state));
 	ret = -EINVAL;

 done:
 	mutex_unlock(&ppd->hls_lock);

 	if (event.device)
 		ib_dispatch_event(&event);

